#!/usr/bin/env python3
"""check-conventions.py - validates the arjuy* C# code conventions. Generated by arjuy-scaffold.

Rules (every violation is an ERROR and makes the script exit with code 1):
  R1  ONE top-level type per .cs file (class, interface, enum, struct, record).
  R2  The file name equals the type name (generic arity ignored: Foo<T> -> Foo.cs).
      Partial types may use 'Type.Suffix.cs'.
  R3  The namespace matches the folder: 'Project.Folder.Sub' for
      'Project/Folder/Sub/File.cs' (the project folder name is the namespace root).
  R4  Identifiers are ASCII (English): accented letters / n-tilde in code identifiers are rejected.
      Strings and comments may be in Spanish.

Usage: python3 scripts/check-conventions.py [path ...]   (default: current directory)
Ignores bin/, obj/, .git/, node_modules/, Migrations/, *.g.cs, *.designer.cs, *.generated.cs.
"""
import os
import re
import sys

IGNORED_DIRS = {"bin", "obj", ".git", "node_modules", "migrations", ".vs", "scripts"}
IGNORED_SUFFIXES = (".g.cs", ".designer.cs", ".generated.cs", ".assemblyinfo.cs", ".globalusings.g.cs")
TYPE_KEYWORDS = {"class", "interface", "enum", "struct", "record"}
NOT_A_NAME = {"where", "new", "notnull", "unmanaged", "class", "struct", "default"}
TOKEN = re.compile(r"[^\W\d]\w*|\{|\}|;|[^\s\w]", re.UNICODE)


def strip_noise(text):
    """Blank out comments, strings and char literals (keeps newlines and length)."""
    out = []
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        two = text[i:i + 2]
        if two == "//":
            while i < n and text[i] != "\n":
                out.append(" ")
                i += 1
        elif two == "/*":
            end = text.find("*/", i + 2)
            end = n if end == -1 else end + 2
            out.append("".join("\n" if ch == "\n" else " " for ch in text[i:end]))
            i = end
        elif text.startswith('"""', i):
            end = text.find('"""', i + 3)
            end = n if end == -1 else end + 3
            out.append("".join("\n" if ch == "\n" else " " for ch in text[i:end]))
            i = end
        elif c == '"' or (c == "@" and two == '@"') or (c == "$" and text[i:i + 2] in ('$"', '$@')) or two == '$@':
            j = i
            verbatim = False
            while j < n and text[j] in "@$":
                verbatim = verbatim or text[j] == "@"
                j += 1
            j += 1  # opening quote
            while j < n:
                if verbatim and text[j] == '"' and text[j:j + 2] == '""':
                    j += 2
                    continue
                if not verbatim and text[j] == "\\":
                    j += 2
                    continue
                if text[j] == '"':
                    j += 1
                    break
                j += 1
            out.append("".join("\n" if ch == "\n" else " " for ch in text[i:j]))
            i = j
        elif c == "'":
            j = i + 1
            while j < n and text[j] != "'":
                j += 2 if text[j] == "\\" else 1
            j += 1
            out.append(" " * (j - i))
            i = j
        else:
            out.append(c)
            i += 1
    return "".join(out)


def analyze(text):
    """Returns (top_level_types, namespace or None, non_ascii_identifiers)."""
    clean = strip_noise(text)
    tokens = TOKEN.findall(clean)
    stack = []            # 'ns' or 'other' per open brace
    pending_ns = False
    types = []
    namespace = None
    non_ascii = set()
    for index, token in enumerate(tokens):
        if token[0].isalpha() or token[0] == "_":
            if not token.isascii():
                non_ascii.add(token)
        if token == "namespace" and all(s == "ns" for s in stack):
            parts = []
            j = index + 1
            while j < len(tokens) and tokens[j] not in ("{", ";"):
                parts.append(tokens[j])
                j += 1
            if namespace is None:
                namespace = "".join(parts)
            pending_ns = j < len(tokens) and tokens[j] == "{"
            continue
        if token == "{":
            stack.append("ns" if pending_ns else "other")
            pending_ns = False
        elif token == "}":
            if stack:
                stack.pop()
        elif token in TYPE_KEYWORDS and all(s == "ns" for s in stack):
            previous = tokens[index - 1] if index > 0 else ""
            nxt = tokens[index + 1] if index + 1 < len(tokens) else ""
            if token == "record" and nxt in ("class", "struct"):
                continue
            if previous in (":", ",", "enum") and token != "record":
                continue  # generic constraint 'where T : class' or 'enum class'
            if nxt and (nxt[0].isalpha() or nxt[0] == "_") and nxt not in NOT_A_NAME:
                types.append(nxt)
    return types, namespace, sorted(non_ascii)


def expected_namespace(path):
    """Namespace derived from the folder: the first folder that looks like a project root ('X' or 'X.Layer')."""
    # the project folder is the nearest ancestor holding a .csproj
    directory = os.path.dirname(os.path.abspath(path))
    project_dir = None
    probe = directory
    while True:
        if any(f.endswith(".csproj") for f in os.listdir(probe)):
            project_dir = probe
            break
        parent = os.path.dirname(probe)
        if parent == probe:
            break
        probe = parent
    if project_dir is None:
        return None
    relative = os.path.relpath(directory, project_dir)
    segments = [os.path.basename(project_dir)]
    if relative != ".":
        segments += relative.split(os.sep)
    return ".".join(segments)


def check_file(path):
    errors = []
    with open(path, encoding="utf-8-sig", errors="replace") as handle:
        text = handle.read()
    types, namespace, non_ascii = analyze(text)
    name = os.path.basename(path)[:-3]
    if len(types) > 1:
        errors.append("R1 %d top-level types in one file (%s); one type per file" % (len(types), ", ".join(types)))
    if types:
        first = types[0]
        if name != first and not name.startswith(first + "."):
            errors.append("R2 file name '%s.cs' does not match type '%s'" % (name, first))
        expected = expected_namespace(path)
        if expected and namespace and namespace != expected:
            errors.append("R3 namespace '%s' does not match folder (expected '%s')" % (namespace, expected))
    if non_ascii:
        errors.append("R4 non-ASCII identifiers (use English identifiers): " + ", ".join(non_ascii))
    return errors


def iter_cs_files(root):
    for current, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
        for file_name in files:
            lower = file_name.lower()
            if lower.endswith(".cs") and not lower.endswith(IGNORED_SUFFIXES):
                yield os.path.join(current, file_name)


def main(argv):
    roots = argv[1:] or ["."]
    checked, violations = 0, 0
    for root in roots:
        for path in sorted(iter_cs_files(root)):
            checked += 1
            for error in check_file(path):
                violations += 1
                print("%s: %s" % (os.path.relpath(path), error))
    print("check-conventions: %d files checked, %d violations" % (checked, violations))
    return 1 if violations else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
